VALUES ('yan-r1', '克', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，名克，西周早期燕侯，通常认为是召公奭之子。琉璃河出土的克罍、克盉铭文记载周王命克为燕侯，并赐予人口与职官；是早期燕国分封的重要见证。具体在位起讫年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯克"},{"label":"首都博物馆：克罍及分封燕侯铭文","url":"https://www.capitalmuseum.org.cn/collection/30a9844041e24d919ad497143c9db47b"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"}]'::jsonb, NULL, NULL, '克')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yan-r2', '旨', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，名旨，西周早期燕侯，见于燕侯旨鼎等青铜器铭文。通常列为克之后的燕君，关于其为克之弟或克之子的关系，学者有不同解释。具体在位起讫年代失考。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯旨"},{"label":"河南博物院：燕侯旨鼎","url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/clzl/zlhg/dszhzgdwh/debfzmds/article301959f6691644fd9661d4e7ed7e351f.html"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]'::jsonb, NULL, NULL, '旨')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yan-r3', '舞', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，名舞，西周早期燕侯，出土铜器有“匽侯舞”等铭文，传世文献未载其政事。学者据铭文考订其世次；与其他早期燕侯的关系及具体在位起讫年代仍有未明之处。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕侯舞"},{"label":"燕国君主列表及所据考古、世系研究","url":"https://zh.wikipedia.org/wiki/燕国#君主列表"}]'::jsonb, NULL, NULL, '舞')
