VALUES ('yan-r5', '庄', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '燕惠侯之子，名庄，谥釐侯，前826—前791年在位。其二十一年郑桓公初封于郑；在位三十六年而卒，子顷侯继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕釐侯"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/zh-hans/史記/卷014"}]'::jsonb, '釐侯', NULL, '燕釐侯')
