VALUES ('yan-r6', '顷侯', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥顷侯。事迹在《史记·燕世家》及后世追述中甚略，前790–前767年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕顷侯"}]'::jsonb, '顷侯', NULL, '燕顷侯')
