VALUES ('yan-r7', '哀侯', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥哀侯，在位仅二年。卒后由郑侯继立，事迹载录甚略，前766–前765年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕哀侯"}]'::jsonb, '哀侯', NULL, '燕哀侯')
