VALUES ('yan-r8', '郑侯', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥郑侯。相传在位三十六年，事迹载录甚略，年代见于《燕世家》，前764–前729年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕郑侯"}]'::jsonb, '郑侯', NULL, '燕郑侯')
