VALUES ('yan-r11', '桓侯', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥桓侯，在位七年。事迹多见世系记载，政事不见详载，前697–前691年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓侯"}]'::jsonb, '桓侯', NULL, '燕桓侯')
