VALUES ('yan-r12', '庄公', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '燕桓侯之后，前690—前658年在位。曾与宋、卫参与拥立王子颓；后来山戎侵燕，齐桓公出兵救援，燕君送齐桓公出境，齐以所至之地赠燕。卒后子襄公继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕庄公"},{"label":"《史记·燕召公世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷034"}]'::jsonb, '庄公', NULL, '燕庄公')
