VALUES ('yan-r13', '襄公', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥襄公，庄公之子。在位近四十年，燕国仍居东偏小国之列，前657–前618年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕襄公"}]'::jsonb, '襄公', NULL, '燕襄公')
