VALUES ('yan-r14', '桓公', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '谥桓，有两段在位：前617–前602年与前372–前362年；或为同名异君，史家有争议。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕桓公"}]'::jsonb, '桓公', NULL, '燕桓公')
