VALUES ('yan-r15', '宣公', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬姓，谥宣公，在位十四年。春秋中期燕国仍多赖世系记载，前601–前587年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕宣公"}]'::jsonb, '宣公', NULL, '燕宣公')
