VALUES ('yan-r30', '文公', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '燕后文公，燕桓公之后、燕易王之父，前361—前333年在位。燕国君主世系表将其与春秋时期燕前文公区分；本名失载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕后文公"}]'::jsonb, '文公', NULL, '燕后文公')
