VALUES ('yan-r32', '哙', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬哙，无谥。听信邹子之等，禅位于相子之，引发内乱，齐国田章破燕，哙死，前320–前314年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/哙"}]'::jsonb, NULL, NULL, '哙')
