VALUES ('yan-r33', '职', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬职，燕王哙庶兄。流落赵国后复国即位；用乐毅、邹衍等，合五国伐齐，占齐七十余城，前312–前279年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕昭王"}]'::jsonb, '昭王', NULL, '燕昭王')
