VALUES ('yan-r34', '惠王', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '谥惠（战国）。疑乐毅而召还，乐毅奔赵；后与齐、秦较量，前278–前271年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕惠王"}]'::jsonb, '惠王', NULL, '燕惠王')
