VALUES ('yan-r35', '讙', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬讙，谥武成。在位十二年，燕国国力经昭惠之后已不如前，前270–前258年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕武成王"}]'::jsonb, '武成王', NULL, '燕武成王')
