VALUES ('yan-r36', '遇', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬遇，谥孝王（战国）。在位仅三年，事迹载录甚略，年代见于《燕世家》，前257–前255年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/燕孝王"}]'::jsonb, '孝王', NULL, '燕孝王')
