VALUES ('yan-r37', '喜', ARRAY[]::text[], '姬', '匽', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '姬喜，无谥。秦将王翦、李信攻燕，喜逃亡辽东，后被俘处死，燕亡，前254–前222年在位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/喜"}]'::jsonb, NULL, NULL, '喜')
